Here the infix expression is turned into a small expression tree first. The parser creates an operator node after reading its left and right parts. A postorder walk then visits left side, right side, and operator, which is exactly postfix order.

The parser methods are arranged by priority. `^` parses its right side recursively so exponentiation stays right-associative.

```csharp
class Solution {
    private class Node {
        public char Value;
        public Node Left;
        public Node Right;

        public Node(char value, Node left = null, Node right = null) {
            Value = value;
            Left = left;
            Right = right;
        }
    }

    private string text;
    private int position;

    public string InfixToPostfix(string s) {
        text = s;
        position = 0;
        Node root = ParseExpression();
        StringBuilder result = new StringBuilder();
        WritePostfix(root, result);
        return result.ToString();
    }

    private Node ParseExpression() {
        Node left = ParseTerm();
        SkipSpaces();

        while (position < text.Length && (text[position] == '+' || text[position] == '-')) {
            char op = text[position++];
            Node right = ParseTerm();
            left = new Node(op, left, right);
            SkipSpaces();
        }
        return left;
    }

    private Node ParseTerm() {
        Node left = ParsePower();
        SkipSpaces();

        while (position < text.Length && (text[position] == '*' || text[position] == '/')) {
            char op = text[position++];
            Node right = ParsePower();
            left = new Node(op, left, right);
            SkipSpaces();
        }
        return left;
    }

    private Node ParsePower() {
        Node left = ParsePrimary();
        SkipSpaces();

        if (position < text.Length && text[position] == '^') {
            position++;
            Node right = ParsePower();
            return new Node('^', left, right);
        }
        return left;
    }

    private Node ParsePrimary() {
        SkipSpaces();

        if (text[position] == '(') {
            position++;
            Node inside = ParseExpression();
            SkipSpaces();
            if (position < text.Length && text[position] == ')') {
                position++;
            }
            return inside;
        }

        return new Node(text[position++]);
    }

    private void SkipSpaces() {
        while (position < text.Length && char.IsWhiteSpace(text[position])) {
            position++;
        }
    }

    private void WritePostfix(Node node, StringBuilder result) {
        if (node == null) {
            return;
        }
        WritePostfix(node.Left, result);
        WritePostfix(node.Right, result);
        result.Append(node.Value);
    }
}
```

For `(a+b)*c`, the tree stores `+` below the parentheses and `*` at the root. Postorder visits `a`, `b`, `+`, `c`, and `*`, giving `ab+c*`.

The code does not change the input string. Important cases such as a single operand, spaces, and nested parentheses are handled by the parser.

Time complexity: `O(n)`.
Space complexity: `O(n)` for the expression tree and recursion stack.

Kept the usual operator stack here. Operands go straight to the result, while operators wait until the stack has no operator with higher or equal priority above them. Parentheses only control when operators are removed.

For example, `a+b*c` becomes `abc*+`: multiplication is popped after `c`, before addition.

```cpp
class Solution {
public:
    string infixToPostfix(string s) {
        stack<char> operators;
        string result;

        auto isOperand = [](char c) {
            return isalnum(static_cast<unsigned char>(c));
        };

        auto precedence = [](char c) {
            if (c == '^') return 3;
            if (c == '*' || c == '/') return 2;
            if (c == '+' || c == '-') return 1;
            return 0;
        };

        for (char c : s) {
            if (isspace(static_cast<unsigned char>(c))) {
                continue;
            }

            if (isOperand(c)) {
                result += c;
            } else if (c == '(') {
                operators.push(c);
            } else if (c == ')') {
                while (!operators.empty() && operators.top() != '(') {
                    result += operators.top();
                    operators.pop();
                }
                if (!operators.empty()) {
                    operators.pop();
                }
            } else {
                while (!operators.empty() && operators.top() != '(' &&
                       (precedence(operators.top()) > precedence(c) ||
                        (precedence(operators.top()) == precedence(c) && c != '^'))) {
                    result += operators.top();
                    operators.pop();
                }
                operators.push(c);
            }
        }

        while (!operators.empty()) {
            if (operators.top() != '(') {
                result += operators.top();
            }
            operators.pop();
        }

        return result;
    }
};
```

Dry run for `a+b*c`: `a` is added, `+` is stored, `b` is added, and `*` is stored above `+`. After `c`, the remaining stack is popped as `*` then `+`, giving `abc*+`.

Time complexity: `O(n)` because every character is pushed and popped at most once.
Space complexity: `O(n)` for the operator stack and result.

The main check is whether the operator on the stack should be written before the current operator. The exponent operator is the only right-associative one here, so another `^` should not remove the earlier `^` too soon.

Spaces are ignored, and parentheses are removed without being added to the answer.

```java
class Solution {
    public String infixToPostfix(String s) {
        StringBuilder result = new StringBuilder();
        Deque<Character> stack = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char current = s.charAt(i);

            if (Character.isWhitespace(current)) {
                continue;
            }

            if (Character.isLetterOrDigit(current)) {
                result.append(current);
            } else if (current == '(') {
                stack.push(current);
            } else if (current == ')') {
                while (!stack.isEmpty() && stack.peek() != '(') {
                    result.append(stack.pop());
                }
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                while (!stack.isEmpty() && stack.peek() != '(' &&
                       (priority(stack.peek()) > priority(current) ||
                        (priority(stack.peek()) == priority(current) && current != '^'))) {
                    result.append(stack.pop());
                }
                stack.push(current);
            }
        }

        while (!stack.isEmpty()) {
            result.append(stack.pop());
        }

        return result.toString();
    }

    private int priority(char operator) {
        if (operator == '^') return 3;
        if (operator == '*' || operator == '/') return 2;
        if (operator == '+' || operator == '-') return 1;
        return 0;
    }
}
```

An input such as `a+b` leaves `+` on the stack until the scan ends, so the final answer is `ab+`. The same cleanup also works when the expression ends with a closing parenthesis.

Time: `O(n)`.
Space: `O(n)` in the worst case, mainly for nested parentheses and operators.

